async ({ http: { request }, gh: { api } }) => {
  const [doc, iss, search] = await Promise.all([
    request("https://raw.githubusercontent.com/cv/pi-action/main/docs/extensions.md", { maxBytes: 200000 }),
    api("repos/cv/pi-action/issues/80"),
    api("search/code?q=present+repo:cv/pi-action"),
  ]);
  const b = String(doc.body);
  const i = b.indexOf("workflow log");
  return { status: doc.status, excerpt: b.slice(Math.max(0, i - 200), i + 6000), iss: iss.stdout.slice(0, 2500), search: search.stdout.slice(0, 1500) };
}
